24:   // Hence, we manually prevent the handleClick callback from being invoked as soon as the button is pressed once.
25:   const shouldOnClickBeCalled = useRef(true);
26: 
27:   const labTile = (
28:     <div className={styles.orderBasketItemTile}>
29:       <div>
30:         <OrderActionLabel orderBasketItem={orderBasketItem} />
31:         <br />
32:         <span className={styles.name}>{orderBasketItem.concept?.display}</span>
33:         <span className={styles.label01}>
34:           {!!orderBasketItem.orderError && (
35:             <>
36:               <br />
37:               <span className={styles.orderErrorText}>
38:                 <WarningIcon size={16} />
39:                 &nbsp;
40:                 <span className={styles.label01}>{t('error', 'Error').toUpperCase()}</span> &nbsp;
