42:               </span>
43:             </>
44:           )}
45:         </span>
46:       </div>
47:       <Button
48:         className={styles.removeButton}
49:         kind="ghost"
50:         hasIconOnly={true}
51:         renderIcon={(props: ComponentProps<typeof TrashCanIcon>) => <TrashCanIcon size={16} {...props} />}
52:         iconDescription={t('removeFromBasket', 'Remove from basket')}
53:         onClick={() => {
54:           shouldOnClickBeCalled.current = false;
55:           onRemoveClick();
56:         }}
57:         tooltipPosition="left"
58:       />
59:     </div>
60:   );
61:   return orderBasketItem.action === 'DISCONTINUE' ? (
62:     <Tile>{labTile}</Tile>
63:   ) : (
64:     <ClickableTile
65:       role="listitem"
66:       className={classNames({
67:         [styles.clickableTileTablet]: isTablet,
68:         [styles.clickableTileDesktop]: !isTablet,
69:       })}
70:       onClick={() => shouldOnClickBeCalled.current && onItemClick()}
71:     >
72:       {labTile}
73:     </ClickableTile>
74:   );
75: };
